ALTER TABLE review_items ADD COLUMN missing_fields_json TEXT CHECK(missing_fields_json IS NULL OR (length(missing_fields_json)<=100 AND json_valid(missing_fields_json) AND json_type(missing_fields_json)='array' AND json_array_length(missing_fields_json) BETWEEN 1 AND 4 AND (json_array_length(missing_fields_json)<=0 OR (json_type(missing_fields_json,'$[0]')='text' AND json_extract(missing_fields_json,'$[0]') IN ('merchant','currency','total','documentDate'))) AND (json_array_length(missing_fields_json)<=1 OR (json_type(missing_fields_json,'$[1]')='text' AND json_extract(missing_fields_json,'$[1]') IN ('merchant','currency','total','documentDate'))) AND (json_array_length(missing_fields_json)<=2 OR (json_type(missing_fields_json,'$[2]')='text' AND json_extract(missing_fields_json,'$[2]') IN ('merchant','currency','total','documentDate'))) AND (json_array_length(missing_fields_json)<=3 OR (json_type(missing_fields_json,'$[3]')='text' AND json_extract(missing_fields_json,'$[3]') IN ('merchant','currency','total','documentDate'))) AND (json_array_length(missing_fields_json)<=1 OR json_extract(missing_fields_json,'$[0]') IS NOT json_extract(missing_fields_json,'$[1]')) AND (json_array_length(missing_fields_json)<=2 OR json_extract(missing_fields_json,'$[0]') IS NOT json_extract(missing_fields_json,'$[2]')) AND (json_array_length(missing_fields_json)<=3 OR json_extract(missing_fields_json,'$[0]') IS NOT json_extract(missing_fields_json,'$[3]')) AND (json_array_length(missing_fields_json)<=2 OR json_extract(missing_fields_json,'$[1]') IS NOT json_extract(missing_fields_json,'$[2]')) AND (json_array_length(missing_fields_json)<=3 OR json_extract(missing_fields_json,'$[1]') IS NOT json_extract(missing_fields_json,'$[3]')) AND (json_array_length(missing_fields_json)<=3 OR json_extract(missing_fields_json,'$[2]') IS NOT json_extract(missing_fields_json,'$[3]'))));
